/* @lc app=leetcode id=3604 lang=kotlin */ class Solution { fun minTime(n: Int, edges: Array<IntArray>): Int = edges.groupBy { it[0] }.let { g -> IntArray(n) { Int.MAX_VALUE }.also { it[0] = 0 }.let { d -> java.util.PriorityQueue<IntArray>(compareBy<IntArray> { it[0] }).also { it.add(intArrayOf(0, 0)) }.let { pq -> generateSequence { pq.poll() }.filter { (t, u) -> t == d[u] }.forEach { (t, u) -> g[u].orEmpty().filter { e -> maxOf(t, e[2]) <= e[3] && maxOf(t, e[2]) + 1 < d[e[1]] }.forEach { e -> pq.add(intArrayOf(maxOf(t, e[2]) + 1, e[1])).also { d[e[1]] = maxOf(t, e[2]) + 1 } } }.let { d[n - 1].let { if (it == Int.MAX_VALUE) -1 else it } } } } } }